from pathlib import Path
import re

path = Path('/home/ubuntu/medical-visit-manager/components/report-variant-screen.tsx')
text = path.read_text()
replacement = r'''function MonthlyRepresentativeTable({ visits, entities, year }: { visits: Visit[]; entities: { id: string; name: string }[]; year: number }) {
  const [selectedCell, setSelectedCell] = useState<{ doctor: string; month: string; visits: Visit[] } | null>(null);
  const [doctorSearch, setDoctorSearch] = useState("");
  const [sortByAnnual, setSortByAnnual] = useState<"asc" | "desc">("desc");
  const doctorRows = useMemo(() => {
    const byDoctor = new Map<string, { id: string; name: string; counts: number[] }>();
    visits.forEach((visit) => {
      const date = new Date(visit.recordedAt);
      if (Number.isNaN(date.getTime()) || date.getFullYear() !== year) return;
      const key = visit.entityId || visit.entityName;
      const current = byDoctor.get(key) ?? { id: key, name: entities.find((entity) => entity.id === visit.entityId)?.name ?? visit.entityName, counts: Array.from({ length: 12 }, () => 0) };
      current.counts[date.getMonth()] += 1;
      byDoctor.set(key, current);
    });
    const normalizedSearch = doctorSearch.trim().toLowerCase();
    return [...byDoctor.values()].filter((row) => !normalizedSearch || row.name.toLowerCase().includes(normalizedSearch)).sort((left, right) => {
      const leftAnnual = left.counts.reduce((sum, count) => sum + count, 0);
      const rightAnnual = right.counts.reduce((sum, count) => sum + count, 0);
      return sortByAnnual === "asc" ? leftAnnual - rightAnnual || left.name.localeCompare(right.name, "ar") : rightAnnual - leftAnnual || left.name.localeCompare(right.name, "ar");
    });
  }, [doctorSearch, entities, sortByAnnual, visits, year]);
  const totals = doctorRows.reduce((sum, row) => sum.map((value, index) => value + row.counts[index]), Array.from({ length: 12 }, () => 0));
  const orderedMonths = MONTH_ABBR.slice().reverse();
  const monthWidth = 92;
  const fixedWidth = 190;
  const cellStyle = { borderLeftWidth: 1, borderBottomWidth: 1, borderColor: "#22313F", minHeight: 58, paddingHorizontal: 5, alignItems: "center" as const, justifyContent: "center" as const };
  const openDetails = (doctor: { id: string; name: string }, monthName: string, monthIndex: number) => {
    const selectedVisits = visits.filter((visit) => {
      const date = new Date(visit.recordedAt);
      return !Number.isNaN(date.getTime()) && date.getFullYear() === year && date.getMonth() === monthIndex && (visit.entityId || visit.entityName) === doctor.id;
    });
    setSelectedCell({ doctor: doctor.name, month: `${monthName}-${year}`, visits: selectedVisits });
  };
  return <View className="rounded-2xl border-2 border-[#22313F] overflow-hidden bg-surface"><View className="px-4 py-3 bg-[#F8FBFF] border-b border-border"><Text className="text-foreground font-bold text-right">الزيارات الشهرية حسب المندوب</Text><Text className="text-muted text-[10px] text-right mt-1">اضغط على أي عدد شهري لعرض تفاصيل الزيارات</Text><View style={{ flexDirection: "row-reverse", gap: 8, marginTop: 10 }}><TextInput value={doctorSearch} onChangeText={setDoctorSearch} placeholder="بحث باسم الطبيب" placeholderTextColor="#7C8798" textAlign="right" style={{ flex: 1, minHeight: 42, borderRadius: 10, borderWidth: 1, borderColor: "#B7CDE5", backgroundColor: "#FFFFFF", paddingHorizontal: 12, color: "#102A43" }} /><Pressable onPress={() => setSortByAnnual((current) => current === "asc" ? "desc" : "asc")} accessibilityRole="button" accessibilityLabel="فرز حسب إجمالي السنة" style={{ minHeight: 42, paddingHorizontal: 12, borderRadius: 10, backgroundColor: "#EAF3FB", borderWidth: 1, borderColor: "#B7CDE5", justifyContent: "center" }}><Text style={{ color: "#1257A6", fontSize: 11, fontWeight: "800" }}>الإجمالي {sortByAnnual === "asc" ? "تصاعدي" : "تنازلي"}</Text></Pressable></View></View><View style={{ flexDirection: "row-reverse" }}><View style={{ width: fixedWidth, backgroundColor: "#FFFFFF" }}><View style={[cellStyle, { backgroundColor: "#BFE8D6" }]} /><View style={[cellStyle, { backgroundColor: "#BFE8D6" }]}><Text style={{ color: "#1257A6", fontSize: 12, fontWeight: "800", textAlign: "center" }}>اسم الطبيب</Text></View>{doctorRows.map((row) => <View key={row.id} style={[cellStyle, { alignItems: "flex-end", backgroundColor: "#F8FBFF" }]}><Text style={{ color: "#102A43", fontSize: 12, fontWeight: "700", textAlign: "right" }} numberOfLines={2}>{row.name}</Text></View>)}<View style={[cellStyle, { alignItems: "flex-end", backgroundColor: "#DBEAFE" }]}><Text style={{ color: "#123B68", fontSize: 12, fontWeight: "800", textAlign: "right" }}>الإجمالي السنوي</Text></View></View><ScrollView horizontal showsHorizontalScrollIndicator nestedScrollEnabled contentContainerStyle={{ minWidth: monthWidth * 12 }}><View style={{ minWidth: monthWidth * 12 }}><View style={{ flexDirection: "row-reverse" }}>{orderedMonths.map((monthName) => <View key={monthName} style={[cellStyle, { width: monthWidth, backgroundColor: "#BFE8D6" }]}><Text style={{ color: "#123B68", fontSize: 12, fontWeight: "800", textAlign: "center" }}>{monthName}-{year}</Text></View>)}<View style={[cellStyle, { width: monthWidth, backgroundColor: "#BFE8D6" }]}><Text style={{ color: "#123B68", fontSize: 11, fontWeight: "800", textAlign: "center" }}>إجمالي السنة</Text></View></View><View style={{ flexDirection: "row-reverse" }}>{orderedMonths.map((monthName) => <View key={monthName} style={[cellStyle, { width: monthWidth, backgroundColor: "#DFF3FF" }]}><Text style={{ color: "#1257A6", fontSize: 11, fontWeight: "800", textAlign: "center" }}>عدد الزيارات</Text></View>)}<View style={[cellStyle, { width: monthWidth, backgroundColor: "#DFF3FF" }]}><Text style={{ color: "#1257A6", fontSize: 11, fontWeight: "800", textAlign: "center" }}>عدد الزيارات</Text></View></View>{doctorRows.map((row, rowIndex) => <View key={row.id} style={{ flexDirection: "row-reverse" }}>{row.counts.slice().reverse().map((count, monthIndex) => { const actualMonthIndex = 11 - monthIndex; const monthName = MONTH_ABBR[actualMonthIndex]; return <Pressable key={`${row.id}-${actualMonthIndex}`} onPress={() => openDetails(row, monthName, actualMonthIndex)} accessibilityRole="button" accessibilityLabel={`تفاصيل زيارات ${row.name} في ${monthName} ${year}`} style={({ pressed }) => [cellStyle, { width: monthWidth, backgroundColor: rowIndex % 2 ? "#FFFFFF" : "#F8FBFF" }, pressed && { backgroundColor: "#B8D8F2" }]}><Text style={{ color: count ? "#1257A6" : "#7C8798", fontSize: 13, fontWeight: count ? "800" : "500", textAlign: "center" }}>{count || "—"}</Text></Pressable>; })}<View style={[cellStyle, { width: monthWidth, backgroundColor: rowIndex % 2 ? "#FFFFFF" : "#F8FBFF" }]}><Text style={{ color: "#1257A6", fontSize: 13, fontWeight: "800", textAlign: "center" }}>{row.counts.reduce((sum, count) => sum + count, 0) || "—"}</Text></View></View>)}<View style={{ flexDirection: "row-reverse" }}>{totals.slice().reverse().map((total, monthIndex) => <View key={`total-${monthIndex}`} style={[cellStyle, { width: monthWidth, backgroundColor: "#DBEAFE" }]}><Text style={{ color: "#123B68", fontSize: 13, fontWeight: "800", textAlign: "center" }}>{total}</Text></View>)}<View style={[cellStyle, { width: monthWidth, backgroundColor: "#DBEAFE" }]}><Text style={{ color: "#123B68", fontSize: 13, fontWeight: "800", textAlign: "center" }}>{totals.reduce((sum, count) => sum + count, 0)}</Text></View></View>{!doctorRows.length ? <View style={{ padding: 32, alignItems: "center" }}><MaterialIcons name="inbox" size={32} color="#7C8798" /><Text className="text-muted font-bold mt-2">لا توجد زيارات للسنة المحددة</Text></View> : null}</View></ScrollView></View><Modal visible={Boolean(selectedCell)} transparent animationType="fade" onRequestClose={() => setSelectedCell(null)}><Pressable onPress={() => setSelectedCell(null)} style={{ flex: 1, backgroundColor: "rgba(0,0,0,0.35)", justifyContent: "center", padding: 20 }}><Pressable onPress={(event) => event.stopPropagation()} style={{ width: "100%", maxWidth: 500, maxHeight: "78%", alignSelf: "center", borderRadius: 20, backgroundColor: "#FFFFFF", overflow: "hidden" }}><View style={{ padding: 16, backgroundColor: "#1257A6", flexDirection: "row-reverse", alignItems: "center", justifyContent: "space-between" }}><View style={{ flexDirection: "row-reverse", gap: 8 }}><Pressable onPress={() => { if (!selectedCell) return; void createMonthlyVisitDetailsCsvFile(selectedCell.visits, selectedCell.doctor, selectedCell.month).then((uri) => shareOrDownloadFile(uri, "text/csv")).catch(() => Alert.alert("تعذر التصدير", "لم يتم إنشاء ملف تفاصيل الزيارات.")); }} accessibilityRole="button" accessibilityLabel="تصدير تفاصيل الزيارات" style={{ width: 34, height: 34, borderRadius: 10, backgroundColor: "rgba(255,255,255,0.18)", alignItems: "center", justifyContent: "center" }}><MaterialIcons name="download" size={19} color="#FFFFFF" /></Pressable><Pressable onPress={() => setSelectedCell(null)} accessibilityRole="button" accessibilityLabel="إغلاق التفاصيل" style={{ width: 34, height: 34, borderRadius: 10, backgroundColor: "rgba(255,255,255,0.18)", alignItems: "center", justifyContent: "center" }}><MaterialIcons name="close" size={20} color="#FFFFFF" /></Pressable></View><View style={{ flex: 1, marginRight: 10 }}><Text style={{ color: "#FFFFFF", fontSize: 16, fontWeight: "800", textAlign: "right" }}>{selectedCell?.month}</Text><Text style={{ color: "#DFF3FF", fontSize: 12, textAlign: "right", marginTop: 3 }}>{selectedCell?.doctor}</Text></View></View><ScrollView contentContainerStyle={{ padding: 16 }}>{selectedCell?.visits.length ? selectedCell.visits.map((visit, index) => <View key={visit.id} style={{ paddingVertical: 11, borderBottomWidth: 1, borderBottomColor: "#E5E7EB" }}><Text style={{ color: "#102A43", fontWeight: "700", textAlign: "right" }}>{index + 1}. {visit.entityName}</Text><Text style={{ color: "#64748B", fontSize: 12, textAlign: "right", marginTop: 4 }}>{new Date(visit.recordedAt).toLocaleString("ar-YE")}</Text><Text style={{ color: "#64748B", fontSize: 12, textAlign: "right", marginTop: 2 }}>{visit.entityAddress || visit.geographicLocation || "لا يوجد عنوان مسجل"}</Text></View>) : <Text style={{ color: "#64748B", textAlign: "center", paddingVertical: 24 }}>لا توجد زيارات في هذا الشهر.</Text>}</ScrollView></Pressable></Pressable></Modal></View>;
}

'''
pattern = r'function MonthlyRepresentativeTable[\s\S]*?\nfunction ReportTableCell'
updated, count = re.subn(pattern, replacement + 'function ReportTableCell', text, count=1)
if count != 1:
    raise SystemExit(f'replacement count={count}')
path.write_text(updated)
